'use strict';
const $=id=>document.getElementById(id),P=window.M2DARPrediction;
const cameras={dashboard:'Dashboard',rearview:'Rearview',right_side_window:'Right-side window'};
const state={samples:[],classes:{},metrics:null,selected:null,file:null,objectURL:null,result:null,exportData:null,api:'',token:'',health:null,busy:false,job:null,requestId:null,load:0,time:0,duration:0};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=(n,d=1)=>(100*n).toFixed(d)+'%',clock=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(Math.floor(n%60)).padStart(2,'0')}`;
let toastTimer;
function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,5000);}
function page(name){if(!['workspace','metrics','classes','backend'].includes(name))name='workspace';document.querySelectorAll('.page').forEach(p=>p.hidden=p.id!=='page-'+name);document.querySelectorAll('[data-page]').forEach(b=>{const active=b.dataset.page===name;b.classList.toggle('active',active);b.setAttribute('aria-current',active?'page':'false');});$('breadcrumb').textContent={workspace:'Video analysis',metrics:'Model performance',classes:'Action library',backend:'Backend plan'}[name];history.replaceState(null,'','#'+name);}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>page(b.dataset.page));window.addEventListener('hashchange',()=>page(location.hash.slice(1)));$('viewMetrics').onclick=()=>page('metrics');$('helpButton').onclick=()=>page('backend');
async function json(url){const r=await fetch(url);if(!r.ok)throw Error(`Could not load data (${r.status}).`);return r.json();}
function download(name,data){const u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function releaseVideo(){const v=$('videoPlayer');v.pause();v.removeAttribute('src');v.removeAttribute('poster');v.load();if(state.objectURL)URL.revokeObjectURL(state.objectURL);state.objectURL=null;}
function renderPrediction(prob,truth=null){const ranked=P.rank(prob),top=ranked[0];$('currentAction').textContent=top?state.classes[top.id]:(state.result?'Uncovered interval':state.file?'Awaiting prediction':'Uncovered interval');$('currentConfidence').textContent=top?pct(top.score):'—';$('confidenceBar').style.width=top?pct(top.score):'0';$('topPredictions').innerHTML=ranked.slice(0,5).map(x=>`<div class="rank-row"><div class="rank-label"><span>${esc(state.classes[x.id])}</span><strong>${pct(x.score)}</strong></div><div class="progress-track"><span style="width:${pct(x.score)}"></span></div></div>`).join('');$('predictionEmpty').hidden=!!top;$('predictionEmpty').textContent=state.result?'No prediction window covers this time.':'Your video is loaded. Predictions will appear after a successful GPU job.';$('groundTruth').hidden=truth===null;if(truth!==null){$('truthLabel').textContent=state.classes[truth];const match=top?.id===truth;$('predictionVerdict').textContent=match?'Matches supplied annotation':'Differs from supplied annotation';$('predictionVerdict').className=match?'':'mismatch';}$('exportResult').disabled=!state.exportData;}
function sampleCards(){ $('sampleScroller').innerHTML=state.samples.map((s,i)=>`<button class="sample-card" data-sample="${esc(s.id)}" aria-label="Load sample ${i+1}: ${esc(s.title)}" aria-pressed="false"><div class="sample-thumb"><img src="${s.poster}" alt="Dashboard view of the labelled ${esc(s.title)} clip" loading="lazy"><span class="sample-time">${clock(s.duration_s)}</span></div><div class="sample-info"><span><i class="sample-number">0${i+1}</i>${esc(s.title)}</span><small>${esc(cameras[s.camera])} · labelled test clip</small></div></button>`).join('');document.querySelectorAll('[data-sample]').forEach(b=>b.onclick=()=>selectSample(b.dataset.sample));}
function selectSample(id){if(state.busy)return toast('Finish the current job before choosing another video.');const s=state.samples.find(s=>s.id===id);if(!s)return;state.load++;releaseVideo();state.selected=s;state.file=null;state.result=null;state.exportData={schema_version:1,source:'saved_independent_test_clip',checkpoint_sha256:P.CHECKPOINT,...s};const v=$('videoPlayer');v.src=s.video;v.poster=s.poster;v.load();$('videoTitle').textContent=s.title;$('cameraBadge').textContent=cameras[s.camera].toUpperCase();$('videoDuration').textContent=clock(s.duration_s);$('videoMeta').textContent='Independent test clip · driver '+s.driver;$('sourceBadge').textContent='SAVED PREDICTION';$('scopeNote').textContent=s.prediction_scope;$('predictionScope').textContent='CLIP-LEVEL PREDICTION';$('predictionDescription').textContent='Saved centre-window output · epoch 170';$('uploadPanel').hidden=true;$('timelinePanel').hidden=true;$('uploadError').textContent='';$('videoInput').value='';document.querySelectorAll('[data-sample]').forEach(b=>{const active=b.dataset.sample===id;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});setPlayerDuration(s.duration_s);}
$('samplesPrevious').onclick=()=>$('sampleScroller').scrollBy({left:-380,behavior:'smooth'});$('samplesNext').onclick=()=>$('sampleScroller').scrollBy({left:380,behavior:'smooth'});
function choose(){if(state.busy)return toast('Finish the current job before changing the video.');$('videoInput').click();}$('chooseVideo').onclick=choose;$('replaceVideo').onclick=choose;
async function acceptFile(file){if(state.busy)return;if(!file)return;const ticket=++state.load;let url;try{if(!/\.(mp4|mov|webm)$/i.test(file.name)||!file.size||file.size>512*1024**2)throw Error('Choose one MP4, MOV or WebM up to 512 MiB.');url=URL.createObjectURL(file);const probe=document.createElement('video');const duration=await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('Could not read video metadata. Try an H.264 MP4.')),15000);probe.onloadedmetadata=()=>{clearTimeout(timer);resolve(probe.duration);};probe.onerror=()=>{clearTimeout(timer);reject(Error('This browser cannot decode the video. Try an H.264 MP4.'));};probe.preload='metadata';probe.src=url;}).finally(()=>{probe.removeAttribute('src');probe.load();});if(ticket!==state.load){URL.revokeObjectURL(url);return;}if(!Number.isFinite(duration)||duration<=0||duration>300)throw Error('Choose a video between 0 and 300 seconds long.');releaseVideo();state.objectURL=url;url=null;state.file=file;state.requestId=null;state.selected=null;state.result=null;state.exportData=null;state.job=null;const v=$('videoPlayer');v.src=state.objectURL;v.load();$('videoTitle').textContent=file.name;$('videoDuration').textContent=clock(duration);$('videoMeta').textContent=`Local preview · ${(file.size/1024**2).toFixed(1)} MiB`;$('sourceBadge').textContent='YOUR VIDEO';$('cameraBadge').textContent=cameras[$('cameraView').value].toUpperCase();$('scopeNote').textContent='Your video stays in this browser until you start a connected GPU job.';$('predictionScope').textContent='PREDICTION PENDING';$('predictionDescription').textContent='No GPU inference has run for this video.';$('uploadPanel').hidden=false;$('timelinePanel').hidden=true;$('jobProgress').hidden=true;$('uploadError').textContent='';$('resumeJob').hidden=true;document.querySelectorAll('[data-sample]').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-pressed','false');});setPlayerDuration(duration);connectionState();page('workspace');}catch(e){if(url)URL.revokeObjectURL(url);toast(e.message);}finally{$('videoInput').value='';}}
$('videoInput').onchange=e=>acceptFile(e.target.files[0]);$('analysisMode').onchange=()=>{state.requestId=null;};$('cameraView').onchange=()=>{state.requestId=null;$('cameraBadge').textContent=cameras[$('cameraView').value].toUpperCase();if(state.file&&state.result){state.result=null;state.exportData=null;$('predictionScope').textContent='PREDICTION PENDING';$('predictionDescription').textContent='Viewpoint changed; run a new job for this metadata.';$('timelinePanel').hidden=true;renderPrediction(null);}};
for(const event of ['dragenter','dragover'])$('dropZone').addEventListener(event,e=>{e.preventDefault();if(!state.busy)$('dropZone').classList.add('dragging');});for(const event of ['dragleave','drop'])$('dropZone').addEventListener(event,e=>{e.preventDefault();$('dropZone').classList.remove('dragging');});$('dropZone').addEventListener('drop',e=>{const fs=e.dataTransfer.files;if(fs.length!==1)return toast('Choose one video at a time.');acceptFile(fs[0]);});
function renderMetrics(){const {test:t,validation:v}=state.metrics;const evaluations=[['Independent test · individual clips','1,748 clips · 19 drivers',t.primary_independent_test],['Independent test · verified three-camera subset','204 groups · 19 drivers',t.verified_synchronized_subset],['Validation · individual clips','456 clips · 8 drivers',v.single_view_clips],['Validation · three-camera groups','152 groups · 8 drivers',v.equal_weight_three_camera_classification]];$('metricsBody').innerHTML=evaluations.map(([name,size,m])=>`<tr><td>${name}</td><td>${size}</td><td>${pct(m.accuracy,2)}</td><td>${pct(m.macro_f1,2)}</td><td>${pct(m.top5_accuracy,2)}</td></tr>`).join('');$('cameraMetrics').innerHTML=Object.entries(t.by_camera).map(([key,m])=>`<div class="camera-perf"><span>${esc(cameras[key])}</span><div class="progress-track"><span style="width:${pct(m.accuracy)}"></span></div><strong>${pct(m.accuracy,2)}</strong></div>`).join('');const ci=t.primary_independent_test.bootstrap.accuracy_95ci;$('testInterval').textContent=`Independent test accuracy: ${pct(t.primary_independent_test.accuracy,2)}. Driver-cluster bootstrap 95% interval: ${pct(ci[0],2)}–${pct(ci[1],2)}.`;$('classMetrics').innerHTML=t.primary_independent_test.per_class.map(m=>`<tr><td>${String(m.class_id).padStart(2,'0')}</td><td>${esc(state.classes[m.class_id])}</td><td>${m.support}</td><td>${pct(m.precision)}</td><td>${pct(m.recall)}</td><td>${pct(m.f1)}</td></tr>`).join('');$('classesGrid').innerHTML=Object.entries(state.classes).map(([id,name])=>`<article class="class-card"><small>CLASS ${String(id).padStart(2,'0')}</small><h2>${esc(name)}</h2><p>${id==='0'?'Baseline driving activity':'Driver activity classification'}</p></article>`).join('');}
$('downloadMetrics').onclick=()=>download('m2dar-labelled-evaluation-metrics.json',state.metrics);$('exportResult').onclick=()=>{if(state.exportData)download('m2dar-prediction.json',state.exportData);};
function connectionState(){const ready=state.health?.inference_available===true;$('connectionTitle').textContent=ready?'GPU backend connected':'Sample mode';$('connectionSubtitle').textContent=ready?'One video per analysis':'Live GPU connection pending';$('runPrediction').disabled=!ready||!state.file||state.busy;$('uploadNotice').textContent=ready?'Ready to send this one video to the GPU backend.':'Connect a GPU backend to generate predictions. Your local preview works now.';}
function connectionDialog(){$('connectionError').textContent='';$('apiUrl').value=state.api||((location.hostname==='localhost'||location.hostname==='127.0.0.1')?location.origin:'');$('connectionDialog').showModal();}$('openConnection').onclick=connectionDialog;$('backendConnect').onclick=connectionDialog;$('closeConnection').onclick=()=>$('connectionDialog').close();
async function api(path,options={}){if(!state.api)throw Error('Connect a GPU backend first.');let r;try{r=await fetch(state.api+path,{...options,headers:{...options.headers,...(state.token?{Authorization:'Bearer '+state.token}:{})},signal:options.signal||AbortSignal.timeout(30000)});}catch(e){throw Error('Backend connection failed. Check the HTTPS address or local SSH tunnel.');}let data;try{data=await r.json();}catch(e){throw Error('The backend returned an invalid response.');}if(!r.ok)throw Error(data.error||`Backend request failed (${r.status}).`);return data;}
$('connectionForm').onsubmit=async e=>{e.preventDefault();if(state.busy){$('connectionError').textContent='Finish or recover the active job before changing its connection.';return;}const previous={api:state.api,token:state.token,health:state.health};try{const u=new URL($('apiUrl').value);if(!['http:','https:'].includes(u.protocol)||u.username||u.password||u.search||u.hash||u.pathname!=='/')throw Error('Enter an HTTP(S) origin without a path, credentials or query.');if(location.protocol==='https:'&&u.protocol==='http:')throw Error('This hosted page requires an HTTPS backend. Use the app through your local SSH tunnel for HTTP.');state.api=u.origin;state.token=$('apiToken').value;state.health=await api('/api/health',{signal:AbortSignal.timeout(10000)});if(typeof state.health.inference_available!=='boolean')throw Error('Incompatible backend health response.');connectionState();$('apiToken').value='';$('connectionDialog').close();toast(state.health.inference_available?'GPU backend connected.':'Connected; GPU inference is unavailable.');}catch(error){Object.assign(state,previous);$('connectionError').textContent=error.message;}};
$('disconnect').onclick=()=>{if(state.busy){$('connectionError').textContent='Recover the active job before disconnecting.';return;}state.api='';state.token='';state.health=null;$('apiToken').value='';connectionState();$('connectionDialog').close();};
function setBusy(value){state.busy=value;for(const id of ['chooseVideo','replaceVideo','cameraView','analysisMode'])$(id).disabled=value;document.querySelectorAll('[data-sample]').forEach(b=>b.disabled=value);connectionState();}
function progress(value,text){$('jobProgress').hidden=false;$('progressBar').style.width=Math.max(0,Math.min(100,value))+'%';$('progressText').textContent=text;}
function showLiveResult(r){P.validateResult(r);state.requestId=null;$('cancelJob').hidden=true;state.result=r;state.exportData=r;state.job=null;$('predictionScope').textContent=r.inference_mode==='clip_center'?'CLIP-LEVEL PREDICTION':'AT THE VIDEO PLAYHEAD';$('predictionDescription').textContent=r.inference_mode==='clip_center'?'One deterministic centre-window classification':'Mean of covering single-camera prediction windows';$('sourceBadge').textContent='GPU PREDICTION';$('scopeNote').textContent=r.inference_mode==='clip_center'?'One centre-window prediction for the clip, not a time-localized annotation. No supplied label is assumed.':'Predictions come from the completed GPU job. Window boundaries are approximate; no supplied annotation is available for this upload.';$('timelinePanel').hidden=r.inference_mode==='clip_center';const v=Object.values(r.views)[0];$('timelineWindows').innerHTML=v.windows.map((w,i)=>{const top=P.rank(w.probabilities)[0];return `<button class="window-button" data-window="${i}">${clock(w.start_s)}–${clock(w.end_s)}<br>${esc(state.classes[top.id])}</button>`;}).join('');document.querySelectorAll('[data-window]').forEach(b=>b.onclick=()=>{seekToTime(v.windows[Number(b.dataset.window)].start_s);});setPlayerDuration(r.duration_s,false);updatePlayhead(state.file?$('videoPlayer').currentTime:0);progress(100,'Prediction completed.');setBusy(false);}
async function pollJob(){if(!state.job)return;$('cancelJob').hidden=false;$('resumeJob').hidden=true;$('discardJob').hidden=true;try{while(state.job){const j=await api('/api/jobs/'+state.job.id);progress(15+.85*(j.progress||0),j.message||j.status);if(j.status==='uploading'){progress(0,'Upload incomplete. Discard this job before submitting the video again.');$('discardJob').hidden=false;return;}if(['failed','cancelled'].includes(j.status)){state.job=null;state.requestId=null;$('cancelJob').hidden=true;setBusy(false);throw Error(j.error||'Job cancelled.');}if(j.status==='completed'){showLiveResult(await api('/api/jobs/'+state.job.id+'/result'));toast('GPU prediction completed.');return;}await new Promise(resolve=>setTimeout(resolve,1500));}}catch(e){$('uploadError').textContent=e.message+(state.job?' The job may still be running. Check it again before submitting another video.':'');$('resumeJob').hidden=!state.job;}}
$('resumeJob').onclick=pollJob;
$('discardJob').onclick=async()=>{if(!state.job)return;try{const j=await api('/api/jobs/'+state.job.id);if(['running','queued'].includes(j.status))throw Error('This job is active. Check its status again.');await api('/api/jobs/'+state.job.id,{method:'DELETE'});state.job=null;$('discardJob').hidden=true;$('resumeJob').hidden=true;$('jobProgress').hidden=true;$('uploadError').textContent='';setBusy(false);toast('Incomplete job discarded.');}catch(e){$('uploadError').textContent=e.message;$('resumeJob').hidden=false;}};
$('runPrediction').onclick=async()=>{if(!state.file||state.busy||!state.health?.inference_available)return;setBusy(true);$('uploadError').textContent='';const view=$('cameraView').value;state.requestId ||= crypto.randomUUID();try{progress(0,'Creating a single-video job…');state.job=await api('/api/jobs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({client_request_id:state.requestId,title:state.file.name.slice(0,120),views:[view],inference_mode:$('analysisMode').value,offsets:{[view]:0}})});$('cancelJob').hidden=false;
 if(state.job.status==='uploading'){progress(5,'Uploading and validating video…');await api(`/api/jobs/${state.job.id}/videos/${view}`,{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:state.file,signal:AbortSignal.timeout(600000)});state.job.status='ready';}
 if(state.job.status==='ready'){progress(15,'Video validated. Starting inference…');await api('/api/jobs/'+state.job.id+'/run',{method:'POST'});}
 await pollJob();}catch(e){$('uploadError').textContent=e.message+(state.job?' Job '+state.job.id+' is retained; recover it before submitting another video.':' Retry uses the same request ID.');if(state.job){$('resumeJob').hidden=false;progress(0,'Connection interrupted; job state needs recovery.');}else setBusy(false);}};
$('cancelJob').onclick=async()=>{if(!state.job)return;try{await api('/api/jobs/'+state.job.id+'/cancel',{method:'POST'});progress(0,'Cancellation requested. Waiting for owned worker to stop…');}catch(e){$('uploadError').textContent=e.message;}};
async function refreshJobs(){if(!state.health){$('jobsList').textContent='Connect the backend to view jobs.';return;}try{const {jobs}=await api('/api/jobs');$('jobsList').innerHTML=jobs.length?jobs.map(j=>`<div class="job-row"><div><strong>${esc(j.title)}</strong><small>${esc(j.status)} · ${new Date(j.created*1000).toLocaleString()}</small></div><div class="button-row">${j.status==='completed'?`<button class="secondary" data-inspect-job="${j.id}">Inspect timeline</button><button class="secondary" data-download-job="${j.id}">↓ Result</button>`:''}${['uploading','receiving','validating','ready','queued','running','cancelling'].includes(j.status)?`<button class="secondary" data-cancel-job="${j.id}">Cancel</button>`:`<button class="secondary" data-delete-job="${j.id}">Delete</button>`}</div></div>`).join(''):'No retained jobs.';document.querySelectorAll('[data-inspect-job]').forEach(b=>b.onclick=()=>inspectStoredJob(b.dataset.inspectJob));document.querySelectorAll('[data-download-job]').forEach(b=>b.onclick=async()=>{try{download('m2dar-'+b.dataset.downloadJob+'.json',await api('/api/jobs/'+b.dataset.downloadJob+'/result'));}catch(e){toast(e.message);}});document.querySelectorAll('[data-cancel-job]').forEach(b=>b.onclick=async()=>{try{await api('/api/jobs/'+b.dataset.cancelJob+'/cancel',{method:'POST'});refreshJobs();}catch(e){toast(e.message);}});document.querySelectorAll('[data-delete-job]').forEach(b=>b.onclick=async()=>{try{await api('/api/jobs/'+b.dataset.deleteJob,{method:'DELETE'});refreshJobs();}catch(e){toast(e.message);}});}catch(e){$('jobsList').textContent=e.message;}}
async function inspectStoredJob(id){if(state.busy)return toast('Finish the active job before opening another result.');try{const r=await api('/api/jobs/'+id+'/result');P.validateResult(r);state.load++;releaseVideo();state.file=null;state.selected=null;state.exportData=null;state.job=null;$('videoTitle').textContent=r.title||'Saved GPU prediction';$('cameraBadge').textContent=cameras[Object.keys(r.views)[0]].toUpperCase();$('videoDuration').textContent=clock(r.duration_s);$('videoMeta').textContent='Saved server result · source video is not loaded in this tab';$('uploadPanel').hidden=true;document.querySelectorAll('[data-sample]').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-pressed','false');});showLiveResult(r);$('scopeNote').textContent='Source video is not loaded. Use the slider to inspect the saved model scores; no new GPU inference is needed.';page('workspace');}catch(e){toast(e.message);}}
$('refreshJobs').onclick=refreshJobs;
$('videoPlayer').addEventListener('timeupdate',()=>updatePlayhead($('videoPlayer').currentTime));$('videoPlayer').addEventListener('error',()=>toast('This video could not be loaded or decoded. Saved prediction data remains available.'));window.addEventListener('beforeunload',()=>{if(state.objectURL)URL.revokeObjectURL(state.objectURL);});
function preciseTime(t){t=Math.max(0,Number.isFinite(t)?t:0);return String(Math.floor(t/60)).padStart(2,'0')+':'+(Math.floor(t%60*10)/10).toFixed(1).padStart(4,'0');}
function setPlayerDuration(duration,reset=true){state.duration=duration;const slider=$('predictionSlider');slider.max=String(P.clampTime(duration,duration));slider.disabled=!(duration>0);$('timelineDuration').textContent=preciseTime(duration);updatePlayhead(reset?0:state.time);}
function updatePlayhead(value){state.time=P.clampTime(value,state.duration);const slider=$('predictionSlider');slider.value=String(state.time);slider.setAttribute('aria-valuetext',preciseTime(state.time)+' of '+preciseTime(state.duration));$('timelineCurrent').textContent=preciseTime(state.time);$('probabilityTime').textContent=preciseTime(state.time);$('timelinePlay').disabled=!state.file&&!state.selected;$('timelinePlay').textContent=$('videoPlayer').paused?'▶':'Ⅱ';$('timelinePlay').setAttribute('aria-label',$('videoPlayer').paused?'Play video':'Pause video');$('previousSlot').disabled=state.time<=0;$('nextSlot').disabled=state.duration<=0||state.time>=state.duration-.00001;
 if(state.result){renderPrediction(P.at(state.result,state.time));if(state.result.inference_mode==='clip_center'){$('timeSlotInfo').textContent='One centre-window prediction for the whole clip; scores stay constant.';}else{const windows=Object.values(state.result.views)[0].windows.filter(w=>w.start_s<=state.time&&state.time<w.end_s);$('timeSlotInfo').textContent=windows.length?`${windows.length} covering prediction window${windows.length===1?'':'s'} · top-five scores averaged at this time`:'No scored window covers this time · prediction unknown';document.querySelectorAll('[data-window]').forEach(b=>{const w=Object.values(state.result.views)[0].windows[Number(b.dataset.window)];const active=w.start_s<=state.time&&state.time<w.end_s;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});}}
 else if(state.selected){renderPrediction(state.selected.probabilities,state.selected.ground_truth);$('timeSlotInfo').textContent='Saved clip-level prediction · scores stay constant while you scrub.';}
 else{renderPrediction(null);$('timeSlotInfo').textContent='Preview only · run full-video inference to see top-five predictions over time.';}}
function seekToTime(t){const v=$('videoPlayer');v.pause();const target=P.clampTime(t,state.duration);if(v.readyState>=1&&Number.isFinite(v.duration))v.currentTime=Math.min(target,Math.max(0,v.duration-.000001));updatePlayhead(target);}
$('predictionSlider').oninput=e=>seekToTime(Number(e.target.value));
$('previousSlot').onclick=()=>seekToTime(P.slotTime(state.result,state.time,-1,state.duration));$('nextSlot').onclick=()=>seekToTime(P.slotTime(state.result,state.time,1,state.duration));
$('timelinePlay').onclick=async()=>{const v=$('videoPlayer');try{if(v.paused){if(v.ended)v.currentTime=0;await v.play();}else v.pause();updatePlayhead(v.currentTime);}catch(e){toast('Could not play the video. You can still scrub saved predictions.');}};
for(const name of ['play','pause','seeking','seeked','ended'])$('videoPlayer').addEventListener(name,()=>updatePlayhead($('videoPlayer').currentTime));
$('videoPlayer').addEventListener('loadedmetadata',()=>{const v=$('videoPlayer');if(state.duration>0)v.currentTime=Math.min(state.time,Math.max(0,v.duration-.000001));updatePlayhead(state.time);});
async function init(){const route=location.hash.slice(1);try{const [classes,samples,metrics]=await Promise.all([json('data/classes.json'),json('data/samples.json'),json('data/metrics.json')]);if(!Array.isArray(samples))throw Error('The sample catalogue is invalid.');for(const s of samples){P.probabilities(s.probabilities);if(!/^assets\/sample_[1-5]\.(mp4)$/.test(s.video)||!/^assets\/sample_[1-5]\.jpg$/.test(s.poster)||!Number.isInteger(s.ground_truth)||s.ground_truth<0||s.ground_truth>15)throw Error('Invalid sample metadata.');}Object.assign(state,{classes,samples,metrics});sampleCards();renderMetrics();if(samples.length){selectSample(samples[0].id);}else{$('sampleArea').hidden=true;$('videoTitle').textContent='Choose a video';$('sourceBadge').textContent='VIDEO PREVIEW';$('videoMeta').textContent='Local preview';$('scopeNote').textContent='Choose a video to preview it or connect a GPU backend for predictions.';$('currentAction').textContent='Choose a video';}page(route);}catch(e){$('currentAction').textContent='Samples unavailable';toast(e.message);}}
init();
